parameters.jsCode:
// Pull all generated content
const meta = $('write_meta').item.json.output;
const intro = $('write_intro').item.json.output.intro;
const body = $('write_body').item.json.output.body_content;
const conclusion = $('write_conclusion').item.json.output.conclusion;
const inputs = $('set_inputs').item.json;

// Article title + slug
const title = meta.article_title;
const slug = title
  .toLowerCase()
  .replace(/[^a-z0-9\s-]/g, '')
  .replace(/\s+/g, '-')
  .replace(/-+/g, '-')
  .replace(/^-|-$/g, '');

// Full markdown
const fullMarkdown = `${intro}\n\n${body}\n\n${conclusion}`;

// Small description for Webflow (first ~200 chars of intro, no markdown)
const smallDescription = intro
  .replace(/[#*_`]/g, '')
  .replace(/\n+/g, ' ')
  .trim()
  .substring(0, 200);

// Markdown → HTML converter
function markdownToHtml(md) {
  let html = md
    // Headings
    .replace(/^#### (.+)$/gm, '<h4>$1</h4>')
    .replace(/^### (.+)$/gm, '<h3>$1</h3>')
    .replace(/^## (.+)$/gm, '<h2>$1</h2>')
    .replace(/^# (.+)$/gm, '<h1>$1</h1>')
    // Bold + italic
    .replace(/\*\*\*(.+?)\*\*\*/g, '<strong><em>$1</em></strong>')
    .replace(/\*\*(.+?)\*\*/g, '<strong>$1</strong>')
    .replace(/\*(.+?)\*/g, '<em>$1</em>')
    // Code inline
    .replace(/`([^`]+)`/g, '<code>$1</code>')
    // Unordered list items
    .replace(/^[-*] (.+)$/gm, '<li>$1</li>')
    // Ordered list items
    .replace(/^\d+\. (.+)$/gm, '<li>$1</li>');

  // Wrap consecutive <li> items in <ul>
  html = html.replace(/((?:<li>.*<\/li>\n?)+)/g, '<ul>$1</ul>');

  // Split into blocks and wrap bare text in <p>
  const blocks = html.split(/\n{2,}/);
  html = blocks
    .map(block => {
      block = block.trim();
      if (!block) return '';
      if (/^<(h[1-6]|ul|ol|li|blockquote|pre|table)/.test(block)) return block;
      // Wrap in paragraph, preserve single line breaks within
      return '<p>' + block.replace(/\n/g, '<br>') + '</p>';
    })
    .filter(Boolean)
    .join('\n');

  return html;
}

const contentHtml = markdownToHtml(fullMarkdown);

return [{
  json: {
    title,
    slug,
    meta_description: meta.meta_description,
    small_description: smallDescription,
    content_html: contentHtml,
    full_markdown: fullMarkdown,
    keyword: inputs.keyword,
    pillar: inputs.pillar
  }
}];

